import numpy as np
from PIL import Image
im=np.array(Image.open('/app/output/initial_egocentric_mirrored_camera.png'));d=np.load('/app/output/initial_depth_egocentric_mirrored_camera.npy')
K=np.array([[989.549,0,432],[0,989.549,240],[0,0,1.]])
E=np.array([[-.000223145,.99999997,.000092619, .000242098],[.706082245,.000223145,-.7081298,-.35099357],[-.7081298,-.000092619,-.70608227,1.76827697]])
Ei=np.linalg.inv(np.vstack([E,[0,0,0,1]])); Ki=np.linalg.inv(K)
def world(u,v):
 z=float(d[v,u]); c=Ki@np.array([u,v,1])*z; return (Ei@np.r_[c,1])[:3]
for label, box in [('rim_back',(175,70,340,100)),('rim_left',(130,100,160,280)),('rim_front',(165,275,330,305)),('interior_floor',(175,130,220,170)),('table_front',(350,350,500,420)),('table_right',(400,200,600,300)),('banana1',(220,145,330,230)),('banana2',(220,195,330,270))]:
 x1,y1,x2,y2=box; vals=[]
 for v in range(y1,y2,2):
  for u in range(x1,x2,2):
   if d[v,u]>0: vals.append(world(u,v))
 a=np.array(vals)
 print(label,'N',len(a),'median',np.median(a,0),'ranges',np.percentile(a,[5,95],axis=0))
print('points')
for uv in [(160,85),(200,80),(300,80),(135,140),(140,250),(170,290),(180,150),(205,120),(400,330),(450,370),(500,300),(450,230),(600,250)]:print(uv,world(*uv),d[uv[1],uv[0]],im[uv[1],uv[0]])
